ALTER TABLE public.socios ADD COLUMN email text;
ALTER TABLE public.patrocinadores ADD COLUMN email_acceso text;
ALTER TABLE public.socios ALTER COLUMN telefono SET DEFAULT '';
CREATE TABLE public.usuario_roles (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL CHECK(email=lower(trim(email)) AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), rol public.club_role NOT NULL,
 socio_id uuid REFERENCES public.socios(id), patrocinador_id uuid REFERENCES public.patrocinadores(id), activo boolean NOT NULL DEFAULT true, creado_por uuid, creado_at timestamptz NOT NULL DEFAULT now(), user_id uuid, nombre text NOT NULL DEFAULT '',
 CONSTRAINT usuario_roles_target CHECK ((rol='socia' AND socio_id IS NOT NULL AND patrocinador_id IS NULL) OR (rol='negocio' AND patrocinador_id IS NOT NULL AND socio_id IS NULL) OR (rol IN ('directiva','super_admin') AND socio_id IS NULL AND patrocinador_id IS NULL)),
 UNIQUE NULLS NOT DISTINCT(email,rol,socio_id,patrocinador_id)
);
GRANT SELECT ON public.usuario_roles TO authenticated;
GRANT ALL ON public.usuario_roles TO service_role;
ALTER TABLE public.usuario_roles ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX usuario_unico_super ON public.usuario_roles(rol) WHERE rol='super_admin' AND activo;
INSERT INTO public.usuario_roles(email,rol,socio_id,patrocinador_id,user_id,nombre)
 SELECT lower(u.email),r.role,CASE WHEN r.role='socia' THEN p.socio_id END,CASE WHEN r.role='negocio' THEN p.patrocinador_id END,r.user_id,coalesce(p.nombre,'') FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id LEFT JOIN public.profiles p ON p.id=r.user_id WHERE u.email IS NOT NULL AND (r.role IN('super_admin','directiva') OR (r.role='socia' AND p.socio_id IS NOT NULL) OR (r.role='negocio' AND p.patrocinador_id IS NOT NULL)) ON CONFLICT DO NOTHING;
UPDATE public.socios s SET email=lower(u.email) FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.socio_id=s.id AND u.email IS NOT NULL;
CREATE TABLE public.usuario_vista(user_id uuid NOT NULL, session_id text NOT NULL, role_id uuid NOT NULL REFERENCES public.usuario_roles(id), PRIMARY KEY(user_id,session_id));
GRANT SELECT ON public.usuario_vista TO authenticated;
GRANT ALL ON public.usuario_vista TO service_role;
ALTER TABLE public.usuario_vista ENABLE ROW LEVEL SECURITY;
CREATE POLICY vista_propia ON public.usuario_vista FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.is_super_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.usuario_roles WHERE user_id=auth.uid() AND activo AND rol='super_admin') $$;
CREATE POLICY usuario_roles_read ON public.usuario_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_super_admin());
CREATE OR REPLACE FUNCTION public.has_club_role(r public.club_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.usuario_roles WHERE user_id=auth.uid() AND activo AND (rol=r OR (r='directiva' AND rol='super_admin'))) $$;
CREATE FUNCTION public.has_role(r public.club_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_club_role(r) $$;
CREATE OR REPLACE FUNCTION public.mi_socio() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.socio_id FROM public.usuario_roles r JOIN public.socios s ON s.id=r.socio_id WHERE r.user_id=auth.uid() AND r.activo AND r.rol='socia' AND s.estado='activa' ORDER BY (r.id=(SELECT role_id FROM public.usuario_vista WHERE user_id=auth.uid() AND session_id=coalesce(auth.jwt()->>'session_id',''))) DESC NULLS LAST,r.creado_at LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.mi_patrocinador() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.patrocinador_id FROM public.usuario_roles r JOIN public.patrocinadores p ON p.id=r.patrocinador_id WHERE r.user_id=auth.uid() AND r.activo AND r.rol='negocio' AND p.activo ORDER BY (r.id=(SELECT role_id FROM public.usuario_vista WHERE user_id=auth.uid() AND session_id=coalesce(auth.jwt()->>'session_id',''))) DESC NULLS LAST,r.creado_at LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.estado_sesion_socia() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.mi_socio() IS NOT NULL THEN 'ok' ELSE 'desactivada' END $$;
CREATE FUNCTION public.enlazar_roles_email() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e text; BEGIN IF auth.uid() IS NULL OR coalesce((auth.jwt()->>'is_anonymous')::boolean,false) THEN RAISE EXCEPTION 'Inicia sesión con tu email'; END IF; SELECT lower(email) INTO e FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF e IS NULL THEN RAISE EXCEPTION 'Verifica tu email'; END IF; UPDATE public.usuario_roles SET user_id=auth.uid() WHERE email=e AND (user_id IS NULL OR user_id=auth.uid()); RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'rol',r.rol,'socio_id',r.socio_id,'patrocinador_id',r.patrocinador_id,'numero_socio',s.numero_socio,'nombre',CASE WHEN r.rol='negocio' THEN p.nombre ELSE coalesce(s.nombre,r.nombre) END) ORDER BY r.creado_at) FROM public.usuario_roles r LEFT JOIN public.socios s ON s.id=r.socio_id LEFT JOIN public.patrocinadores p ON p.id=r.patrocinador_id WHERE r.user_id=auth.uid() AND r.activo AND (r.rol<>'socia' OR s.estado='activa') AND (r.rol<>'negocio' OR p.activo)), '[]'::jsonb); END $$;
CREATE FUNCTION public.elegir_vista(p_role uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.usuario_roles WHERE id=p_role AND user_id=auth.uid() AND activo) THEN RAISE EXCEPTION 'Rol no autorizado'; END IF; INSERT INTO public.usuario_vista(user_id,session_id,role_id) VALUES(auth.uid(),coalesce(auth.jwt()->>'session_id',''),p_role) ON CONFLICT(user_id,session_id) DO UPDATE SET role_id=excluded.role_id; END $$;
CREATE FUNCTION public.roles_email_confirmado() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND NEW.email IS NOT NULL THEN UPDATE public.usuario_roles SET user_id=NEW.id WHERE email=lower(NEW.email) AND (user_id IS NULL OR user_id=NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER roles_email_confirmado AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.roles_email_confirmado();
CREATE TABLE public.solicitudes_socios(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nombre text NOT NULL,email text NOT NULL,telefono text NOT NULL DEFAULT '',mayor_de_edad boolean NOT NULL,consentimiento_at timestamptz NOT NULL DEFAULT now(),temporada text NOT NULL DEFAULT '2026/27',estado text NOT NULL DEFAULT 'pendiente_pago' CHECK(estado IN('pendiente_pago','pagada')),creado_at timestamptz NOT NULL DEFAULT now(),socio_id uuid REFERENCES public.socios(id),pago_referencia text,pago_origen text);
GRANT SELECT ON public.solicitudes_socios TO authenticated;
GRANT ALL ON public.solicitudes_socios TO service_role;
ALTER TABLE public.solicitudes_socios ENABLE ROW LEVEL SECURITY;
CREATE POLICY solicitudes_directiva ON public.solicitudes_socios FOR SELECT TO authenticated USING(public.has_club_role('directiva'));
CREATE UNIQUE INDEX solicitud_pendiente_email ON public.solicitudes_socios(lower(email),temporada) WHERE estado='pendiente_pago';
CREATE FUNCTION public.solicitar_alta(p_nombre text,p_email text,p_telefono text,p_mayor boolean,p_consentimiento boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; e text:=lower(trim(p_email)); BEGIN IF length(trim(p_nombre)) NOT BETWEEN 1 AND 200 OR length(e)>254 OR e !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR p_telefono !~ '^$|^[0-9]{9,15}$' OR p_mayor IS DISTINCT FROM true OR p_consentimiento IS DISTINCT FROM true THEN RAISE EXCEPTION 'Comprueba tus datos y consentimientos'; END IF; INSERT INTO public.solicitudes_socios(nombre,email,telefono,mayor_de_edad) VALUES(trim(p_nombre),e,p_telefono,true) ON CONFLICT(lower(email),temporada) WHERE estado='pendiente_pago' DO UPDATE SET email=excluded.email RETURNING id INTO n; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.validate_club_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='socios' THEN IF length(trim(NEW.nombre))<1 OR length(NEW.nombre)>200 OR NEW.telefono !~ '^$|^[0-9]{9,15}$' THEN RAISE EXCEPTION 'Nombre o teléfono no válido'; END IF; IF TG_OP='INSERT' AND (NEW.email IS NULL OR NEW.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') THEN RAISE EXCEPTION 'Email obligatorio'; END IF; IF NEW.estado='desactivada' AND (NEW.fecha_baja IS NULL OR coalesce(length(trim(NEW.motivo_baja)),0)=0) THEN RAISE EXCEPTION 'Indica fecha y motivo de baja'; END IF; ELSIF TG_TABLE_NAME='patrocinadores' THEN IF NOT NEW.activo AND (NEW.fecha_baja IS NULL OR NEW.motivo_baja IS NULL) THEN RAISE EXCEPTION 'Indica fecha y motivo de baja'; END IF; ELSIF TG_TABLE_NAME='avisos' THEN IF length(trim(NEW.titulo))<1 OR length(NEW.titulo)>200 OR length(trim(NEW.texto))<1 OR length(NEW.texto)>5000 THEN RAISE EXCEPTION 'Aviso no válido'; END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.alta_socio_email(p_nombre text,p_email text,p_telefono text DEFAULT '',p_solicitud uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; e text:=lower(trim(p_email)); BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; IF length(trim(p_nombre)) NOT BETWEEN 1 AND 200 OR length(e)>254 OR e !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR p_telefono !~ '^$|^[0-9]{9,15}$' THEN RAISE EXCEPTION 'Comprueba los datos'; END IF; PERFORM pg_advisory_xact_lock(202627); IF p_solicitud IS NOT NULL THEN PERFORM 1 FROM public.solicitudes_socios WHERE id=p_solicitud AND estado='pendiente_pago' AND email=e FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no disponible'; END IF; END IF; SELECT id INTO n FROM public.socios WHERE lower(email)=e AND temporada='2026/27' AND estado='activa' LIMIT 1; IF n IS NULL THEN INSERT INTO public.socios(nombre,email,telefono,estado,mayor_de_edad,consentimiento_at,fecha_activacion) VALUES(trim(p_nombre),e,p_telefono,'activa',coalesce((SELECT mayor_de_edad FROM public.solicitudes_socios WHERE id=p_solicitud),false),(SELECT consentimiento_at FROM public.solicitudes_socios WHERE id=p_solicitud),now()) RETURNING id INTO n; END IF; INSERT INTO public.usuario_roles(email,rol,socio_id,creado_por,user_id,nombre) VALUES(e,'socia',n,auth.uid(),(SELECT id FROM auth.users WHERE lower(email)=e AND email_confirmed_at IS NOT NULL LIMIT 1),trim(p_nombre)) ON CONFLICT(email,rol,socio_id,patrocinador_id) DO UPDATE SET activo=true; IF p_solicitud IS NOT NULL THEN UPDATE public.solicitudes_socios SET estado='pagada',socio_id=n,pago_origen='efectivo' WHERE id=p_solicitud; END IF; RETURN n; END $$;
CREATE FUNCTION public.asignar_directiva_email(p_nombre text,p_email text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; e text:=lower(trim(p_email)); BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF length(trim(p_nombre)) NOT BETWEEN 1 AND 200 OR length(e)>254 OR e !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Comprueba nombre y email'; END IF; INSERT INTO public.usuario_roles(email,rol,nombre,creado_por,user_id) VALUES(e,'directiva',trim(p_nombre),auth.uid(),(SELECT id FROM auth.users WHERE lower(email)=e AND email_confirmed_at IS NOT NULL LIMIT 1)) ON CONFLICT(email,rol,socio_id,patrocinador_id) DO UPDATE SET activo=true,nombre=excluded.nombre RETURNING id INTO n; RETURN n; END $$;
CREATE FUNCTION public.retirar_directiva_email(p_id uuid,p_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid; BEGIN IF NOT public.is_super_admin() OR length(trim(p_motivo))=0 THEN RAISE EXCEPTION 'Solo Super admin; indica motivo'; END IF; UPDATE public.usuario_roles SET activo=false WHERE id=p_id AND rol='directiva' AND user_id IS DISTINCT FROM auth.uid() RETURNING user_id INTO u; IF NOT FOUND THEN RAISE EXCEPTION 'Acceso no disponible'; END IF; INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo) VALUES(auth.uid(),coalesce(u,auth.uid()),'retirar_directiva',p_motivo); END $$;
CREATE FUNCTION public.asignar_negocio_email(p_id uuid,p_email text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e text:=lower(trim(p_email)); BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; IF length(e)>254 OR e !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Email no válido'; END IF; UPDATE public.patrocinadores SET email_acceso=e WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Negocio no disponible'; END IF; UPDATE public.usuario_roles SET activo=false WHERE patrocinador_id=p_id AND rol='negocio' AND email<>e; INSERT INTO public.usuario_roles(email,rol,patrocinador_id,creado_por,user_id) VALUES(e,'negocio',p_id,auth.uid(),(SELECT id FROM auth.users WHERE lower(email)=e AND email_confirmed_at IS NOT NULL LIMIT 1)) ON CONFLICT(email,rol,socio_id,patrocinador_id) DO UPDATE SET activo=true; END $$;
CREATE FUNCTION public.crear_negocio_email(p_nombre text,p_categoria text,p_direccion text,p_logo text,p_email text,p_titulo text,p_descripcion text,p_condiciones text,p_importe numeric DEFAULT 0) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; IF length(trim(p_nombre)) NOT BETWEEN 1 AND 200 OR length(p_titulo) NOT BETWEEN 1 AND 200 OR p_importe<0 THEN RAISE EXCEPTION 'Datos no válidos'; END IF; INSERT INTO public.patrocinadores(nombre,categoria,direccion,logo_url,pin_hash,importe_patrocinio) VALUES(trim(p_nombre),p_categoria,p_direccion,p_logo,'DISABLED',p_importe) RETURNING id INTO n; INSERT INTO public.ventajas(patrocinador_id,titulo,descripcion,condiciones,destacado) VALUES(n,p_titulo,p_descripcion,p_condiciones,'Socia/o'); PERFORM public.asignar_negocio_email(n,p_email); RETURN n; END $$;
REVOKE ALL ON FUNCTION public.enlazar_roles_email(), public.elegir_vista(uuid), public.alta_socio_email(text,text,text,uuid), public.asignar_directiva_email(text,text), public.retirar_directiva_email(uuid,text), public.asignar_negocio_email(uuid,text), public.crear_negocio_email(text,text,text,text,text,text,text,text,numeric), public.roles_email_confirmado() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.enlazar_roles_email(), public.elegir_vista(uuid), public.alta_socio_email(text,text,text,uuid), public.asignar_directiva_email(text,text), public.retirar_directiva_email(uuid,text), public.asignar_negocio_email(uuid,text), public.crear_negocio_email(text,text,text,text,text,text,text,text,numeric) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.solicitar_alta(text,text,text,boolean,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.solicitar_alta(text,text,text,boolean,boolean) TO anon,authenticated,service_role;
REVOKE EXECUTE ON FUNCTION public.enlazar_socio(text,text),public.entrar_negocio(text),public.reservar_directiva(text,text,uuid),public.vincular_directiva(uuid,uuid),public.quitar_directiva(uuid,text),public.transferir_super_admin(uuid),public.crear_patrocinador(text,text,text,text,text,text,text,text,numeric) FROM PUBLIC,anon,authenticated;
COMMENT ON TABLE public.user_roles IS 'DEPRECATED: replaced by usuario_roles, email-bound multiple roles.';
COMMENT ON COLUMN public.socios.token_invitacion IS 'DEPRECATED: access is now verified email only.';
COMMENT ON COLUMN public.patrocinadores.pin_hash IS 'DEPRECATED: access is now verified email only.';
GRANT SELECT(email_acceso) ON public.patrocinadores TO authenticated;